const drums = stack(
  s("bd*4").gain(0.95).duckorbit(2).duckattack(0.15).duckdepth(0.7),
  s("hh*8").gain("[0.2 0.35]*4"),
  s("[~ oh]*4").gain(0.3),
  s("~ cp ~ cp").gain(0.5),
).bank("RolandTR909")
const bass = note("<[~ c2 ~ c2 ~ c2 ~ eb2] [~ c2 ~ c2 ~ g1 ~ bb1]>").s("sawtooth")
  .lpf(sine.range(400, 1800).slow(8)).lpq(6).decay(0.15).sustain(0).orbit(2).gain(0.45)
const chords = chord("<Cm7 Cm7 Ab^7 Bb7>").voicing().struct("~ x ~ ~ ~ x ~ ~").s("square")
  .hpf(250).lpf(1400).decay(0.25).sustain(0).room(0.4).gain(0.25)
const lead = chord("<Cm7 Cm7 Ab^7 Bb7>").voicing().arp("0 1 2 3 2 1 2 3").add(note(12)).s("triangle")
  .decay(0.15).sustain(0).delay(0.35).delaytime(0.35).delayfeedback(0.4).gain(0.22)
stack(drums, bass, chords, lead)
